

'use strict';

const DATA = window.REPORT;

const esc = value => String(value == null ? '' : value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const finite = value => typeof value === 'number' && Number.isFinite(value);

const fixed = value => finite(value) ? value.toFixed(4) : null;

const rate = value => finite(value) ? value.toFixed(4) : '<span class="missing">未提供</span>';

const percent = value => finite(value) ? (value * 100).toFixed(2) + '%' : '未提供';

const mean = values => {const good=values.filter(finite);return good.length ? good.reduce((a,b)=>a+b,0)/good.length : null;};

const pp = value => finite(value) ? `<span class="${value < -1e-10 ? 'value-neg' : value > 1e-10 ? 'value-pos' : 'value-zero'}">${value>1e-10?'+':''}${(Math.abs(value)<1e-10?0:value*100).toFixed(2)}<span class="pp">％</span></span>` : '<span class="missing">未提供</span>';

const subjects = Array.isArray(DATA.subjects) ? DATA.subjects : [];

const state = {subject:subjects[0]?.id, group:subjects[0]?.groups?.find(g=>g.name==='全體')?.name || subjects[0]?.groups?.[0]?.name || '全體', baseline:'national', mode:'all',sort:'qid'};

const current = () => subjects.find(s=>s.id===state.subject) || subjects[0];

const choices = subject => (subject.items||[]).filter(i=>i.kind!=='constructed');

const groupData = item => item.groups?.[state.group] || null;

const optionKeys = subject => subject.id==='listening' ? ['A','B','C'] : ['A','B','C','D'];

const wrongStats = (subject,item,groupName=state.group) => {

 const group=item.groups?.[groupName];

 if(!group || !finite(group.n) || group.n<=0 || !group.counts)return {max:null,options:[],high:[],advantage:[],review:false,exception:false};

 const wrong=optionKeys(subject).filter(k=>k!==item.answer).map(k=>({key:k,count:group.counts[k],rate:finite(group.counts[k])?group.counts[k]/group.n:null})).filter(o=>finite(o.rate));

 const max=wrong.length?Math.max(...wrong.map(o=>o.rate)):null;

 const options=wrong.filter(o=>o.rate>0&&Math.abs(o.rate-max)<1e-12).map(o=>o.key),high=wrong.filter(o=>o.rate>0.2);

 const advantage=['national','city'].filter(b=>finite(difference(item,b))&&difference(item,b)>=0.10);

 const exception=advantage.length>0&&finite(max)&&max>0&&high.length===0;

 return {max,options,high,advantage,review:high.length>0||exception,exception};

};

const difference = (item,baseline) => finite(item.school)&&finite(item[baseline]) ? (baseline==='city'?item.deltaCity:item.deltaNational) : null;

const baselineName = () => state.baseline==='city'?'臺中市':'全國';

const compareItems = (subject,baseline=state.baseline) => choices(subject).filter(i=>finite(i.school)&&finite(i[baseline]));

const hasCompare = (subject,baseline) => compareItems(subject,baseline).length>0;

const sourceName = subject => typeof subject.sourceFile==='string'?subject.sourceFile:(subject.sourceFile?.name||'');

function chooseSubject(id,scroll=false){

 const subject=subjects.find(s=>s.id===id);if(!subject)return;

 state.subject=id;state.group=subject.groups?.find(g=>g.name==='全體')?.name||subject.groups?.[0]?.name||'全體';state.mode='all';state.sort='qid';

 state.baseline=hasCompare(subject,'national')?'national':hasCompare(subject,'city')?'city':'national';render();

 if(scroll)document.getElementById('subject-history').scrollIntoView({behavior:'smooth',block:'start'});

}

function renderOverview(){

 document.getElementById('overview').innerHTML=subjects.map(subject=>{

 const summary=subject.summary||{},val=finite(summary.meanSchool)?summary.meanSchool:mean(choices(subject).map(i=>i.school));

 const benchmarks=[finite(summary.meanNational)?'全國 '+percent(summary.meanNational):'',finite(summary.meanCity)?'臺中市 '+percent(summary.meanCity):''].filter(Boolean).join(' · ');

 const gaps=[['national','學校平均－全國平均',summary.meanNational],['city','學校平均－全縣市平均',summary.meanCity]].map(([key,label,benchmark])=>`<div class="overview-gap" data-gap="${key}"><span>${label}</span><strong>${key==='national'&&finite(benchmark)?'約 ':''}${pp(finite(val)&&finite(benchmark)?val-benchmark:null)}</strong></div>`).join('');

 return `<button class="overview-card ${subject.id===state.subject?'active':''}" type="button" data-subject="${esc(subject.id)}" aria-pressed="${subject.id===state.subject}"><div class="overview-head"><strong>${esc(subject.name)}</strong><span class="overview-count">${choices(subject).length} 題選擇題</span></div><div class="overview-value number">${percent(val)}<small>學校逐題均值</small></div><div class="rate-track" aria-hidden="true"><span style="width:${finite(val)?Math.max(0,Math.min(100,val*100)):0}%"></span></div><div class="scale" aria-hidden="true"><span>0%</span><span>100%</span></div><div class="overview-benchmarks">${benchmarks||'外部比較資料：未提供'}</div><div class="overview-gaps">${gaps}</div></button>`;

 }).join('');

 document.querySelectorAll('[data-subject]').forEach(b=>b.addEventListener('click',()=>chooseSubject(b.dataset.subject,true)));

 document.getElementById('subject-tabs').innerHTML=subjects.map(subject=>`<button type="button" role="tab" aria-selected="${subject.id===state.subject}" data-tab="${esc(subject.id)}">${esc(subject.name)}</button>`).join('');

 document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>chooseSubject(b.dataset.tab)));

}

const abilityLabel = item => typeof item.ability==='string' && item.ability.trim() ? item.ability.trim() : '分項能力未提供';

const abilityOrder = subject => [...new Set([...(subject.abilityOrder||[]),...choices(subject).map(abilityLabel).filter(x=>x!=='分項能力未提供')])];

function abilityCompare(subject,a,b){

 const order=abilityOrder(subject),rank=i=>abilityLabel(i)==='分項能力未提供'?Infinity:order.indexOf(abilityLabel(i));

 const da=difference(a,'national'),db=difference(b,'national');

 return (rank(a)-rank(b)) || (finite(da)?da:Infinity)-(finite(db)?db:Infinity) || a.number-b.number;

}

function chooseOrder(order){

 state.mode='all';state.sort=order;

 if(order==='national'||order==='city')state.baseline=order;

 if(order==='ability')state.baseline='national';

 renderSubject();

}

function orderMarkup(subject){

 const active=state.mode==='all'?state.sort:null;

 const buttons=[['qid','1. 按照題號少至多排序'],['national','2. 按照學校減全國差距排序，最弱題在前'],['city','3. 按照學校減全縣市差距排序，最弱題在前'],['ability','4. 先按照分項能力排序，再按照學校減全國差距排序'],['wrong','5. 按照錯誤答案最高比例排序']];

 let note='題號由少至多排列。學校與全國／縣市的差距固定採學校全體；錯選比例隨下方群體選擇更新。';

 if(active==='national'||active==='city'){

   const label=active==='national'?'全國':'全縣市（臺中市）';

   note=hasCompare(subject,active)?`依「學校通過率－${label}通過率」由低至高排列，差距最負的題目排在最前面；若全為正值，優勢最小的題目在前。差距相同時依題號排列，缺少比較值的題目置末。`:`本科尚未提供${label}逐題通過率，無法計算差距；目前保留全部題目，暫依題號順序顯示。`;

 }

 if(active==='wrong')note='列出全部選擇題，依目前群體每題最多人選的錯誤選項比例由高至低排序，不設 20% 門檻，也不要求高於全國或縣市。比例相同時按題號排列；0% 仍保留，缺少資料置末。';

 if(active==='ability'){

   const missing=choices(subject).filter(i=>abilityLabel(i)==='分項能力未提供').length;

   note='先依分項能力分組，再於同一能力內依「學校通過率－全國通過率」由低至高排列，最弱題在前；差距相同時按題號排列，缺少比較值置於同組末尾。';

   if(subject.id==='chinese')note+='國文分類順序：語文知識、文意理解、文本評鑑。';

   if(missing)note+=` 本科 ${missing} 題未提供逐題分項能力對照，列於「分項能力未提供」，不以評量目標自行推定分類。`;

 }

 return `<div class="primary-orders" aria-label="五種主要排列方式">${buttons.map(([key,label])=>`<button type="button" data-order="${key}" aria-pressed="${active===key}">${label}</button>`).join('')}</div><p class="order-explanation" role="status">${esc(note)}</p>`;

}

function subjectHighlights(subject){

 const items=choices(subject),national=compareItems(subject,'national'),avg=mean(items.map(i=>i.school));

 const list=[{title:'本科逐題平均通過率',text:`${items.length} 題選擇題的學校平均通過率為 ${percent(avg)}。`+(national.length?`同題全國平均為 ${percent(mean(national.map(i=>i.national)))}，校減國平均 ${(mean(national.map(i=>difference(i,'national')))*100).toFixed(2)} ％（${national.length} 題配對）。`:'尚未提供全國與縣市逐題比較值；此平均不代表總分或跨科排名。')}];

 if(national.length){

   const first=national.slice().sort((a,b)=>difference(a,'national')-difference(b,'national')||a.number-b.number)[0],v=difference(first,'national');

   list.push({title:v<0?'與全國落差較大的題目':v>0?'相對全國優勢較小的題目':'與全國差距最小值為零',text:`第 ${first.qid} 題「${first.target}」學校通過率 ${percent(first.school)}、全國 ${percent(first.national)}，校減國 ${(v*100).toFixed(2)} ％。`});

 }else{

   const first=items.filter(i=>finite(i.school)).sort((a,b)=>a.school-b.school||a.number-b.number)[0];

   list.push({title:'校內通過率較低的題目',text:first?`第 ${first.qid} 題「${first.target}」全體通過率為 ${percent(first.school)}。這是校內作答情形，尚不能判定與全國的差距。`:'未提供可計算的通過率。'});

 }

 const wrong=items.filter(i=>wrongStats(subject,i).review).sort((a,b)=>wrongStats(subject,b).max-wrongStats(subject,a).max||a.number-b.number),first=wrong[0];

 const concentrated=wrong.filter(i=>wrongStats(subject,i).high.length).length,additional=wrong.filter(i=>wrongStats(subject,i).exception).length;

 list.push({title:`錯選重點標記：${state.group}`,text:wrong.length?`符合重點標記 ${wrong.length} 題：${concentrated} 題錯選超過 20%，另 ${additional} 題因學校高於全國或縣市至少 10 ％而標記。最高錯選為第 ${first.qid} 題 ${wrongStats(subject,first).options.join('、')}，各占 ${percent(wrongStats(subject,first).max)}（本組 ${first.groups[state.group].n} 人）。`:'有 0 題符合本次錯選重點標記條件；仍可查看各題通過率與其他群體反應。'});

 return `<section class="subject-highlights" aria-labelledby="subject-highlights-title"><h3 id="subject-highlights-title">${esc(subject.name)}重點發現</h3><div class="highlights">${list.map(x=>`<article class="highlight"><h3>${esc(x.title)}</h3><p>${esc(x.text)}</p></article>`).join('')}</div></section>`;

}

function shownItems(subject){

 let rows=choices(subject).slice();

 if(state.mode==='lag10')rows=rows.filter(i=>finite(difference(i,state.baseline))).sort((a,b)=>difference(a,state.baseline)-difference(b,state.baseline)||a.number-b.number).slice(0,10);

 if(state.mode==='gaps')rows=rows.filter(i=>finite(difference(i,state.baseline)));

 const sortKey=state.mode==='wrong'?'wrong':state.mode==='lag10'||state.mode==='gaps'?'gap':state.sort;

 rows.sort((a,b)=>{

  if(sortKey==='gap'){const da=difference(a,state.baseline),db=difference(b,state.baseline);return (finite(da)?da:Infinity)-(finite(db)?db:Infinity)||a.number-b.number;}

  if(sortKey==='national'||sortKey==='city'){const da=difference(a,sortKey),db=difference(b,sortKey);return (finite(da)?da:Infinity)-(finite(db)?db:Infinity)||a.number-b.number;}

  if(sortKey==='ability')return abilityCompare(subject,a,b);

  if(sortKey==='school')return (finite(a.school)?a.school:Infinity)-(finite(b.school)?b.school:Infinity)||a.number-b.number;

  if(sortKey==='wrong')return (wrongStats(subject,b).max??-1)-(wrongStats(subject,a).max??-1)||a.number-b.number;

  return a.number-b.number;

 });return rows;

}

function wrongReason(stats){

 const reasons=[];

 if(stats.high.length)reasons.push('錯選 >20%');

 if(stats.advantage.length&&stats.max>0)reasons.push('學校高於'+stats.advantage.map(b=>b==='national'?'全國':'臺中市').join('／')+' ≥10 ％');

 return reasons.join('；');

}

function wrongCell(subject,item){

 const value=wrongStats(subject,item);

 if(!finite(value.max))return '<span class="missing">未提供</span>';

 if(value.max===0)return `<span class="wrong-normal">無實際錯選：0／${groupData(item).n}人（0.00%）</span>`;

 return `<span class="${value.high.length?'wrong-chip':value.exception?'advantage-chip':'wrong-normal'}">${esc(value.options.join('／'))}：${value.options.length>1?'各 ':''}${groupData(item).counts[value.options[0]]}／${groupData(item).n}人（${percent(value.max)}）</span>${value.review?`<small class="wrong-reason">${esc(wrongReason(value))}</small>`:''}`;

}

function averageCell(values){const good=values.filter(finite);return `${rate(mean(good))}<small>有效 ${good.length} 題</small>`;}

function deltaAverageCell(rows,baseline){const values=rows.map(i=>difference(i,baseline)).filter(finite);return `${pp(mean(values))}<small>有效配對 ${values.length} 題</small>`;}

function summaryMarkup(subject){

 const items=choices(subject),summary=subject.summary||{},national=compareItems(subject,'national'),city=compareItems(subject,'city');

 return `<div class="summary-line"><div class="metric"><span class="label">選擇題數</span><strong class="number">${items.length}<small> 題</small></strong></div><div class="metric"><span class="label">學校逐題通過率均值（0–1）</span><strong class="number">${rate(finite(summary.meanSchool)?summary.meanSchool:mean(items.map(i=>i.school)))}</strong></div><div class="metric"><span class="label">對全國平均差距・${national.length} 題配對</span><strong class="number">${pp(mean(national.map(i=>difference(i,'national'))))}</strong></div><div class="metric"><span class="label">對臺中市平均差距・${city.length} 題配對</span><strong class="number">${pp(mean(city.map(i=>difference(i,'city'))))}</strong></div></div>`;

}

function tableMarkup(subject,rows){

 let previousAbility=null;

 const national=rows.filter(i=>finite(i.school)&&finite(i.national)),city=rows.filter(i=>finite(i.school)&&finite(i.city));

 return `<div class="table-caption"><span><strong>目前顯示 ${rows.length}／${choices(subject).length} 題</strong> · 最高錯選使用「${esc(state.group)}」群體</span><span>學校／基準：0–1；最高錯選：百分比；差距：％</span></div><div class="table-wrap"><table class="item-table"><thead><tr><th class="qid">題號</th><th class="ability-label">分項能力</th><th>來源評量目標</th><th class="numeric">全國</th><th class="numeric">臺中市</th><th class="numeric">學校全體</th><th class="numeric">校減國（％）</th><th class="numeric">校減臺中（％）</th><th class="numeric">最高錯選（${esc(state.group)}）</th><th>詳情</th></tr></thead><tbody>${rows.length?rows.map(item=>{const ability=abilityLabel(item),divider=state.sort==='ability'&&state.mode!=='lag10'&&state.mode!=='gaps'&&ability!==previousAbility?`<tr class="ability-divider"><td colspan="10">${esc(ability)}<small>同組按學校減全國差距由低至高排列</small></td></tr>`:'';previousAbility=ability;return `${divider}<tr><td class="qid">${esc(item.qid)}</td><td class="ability-label">${esc(ability)}</td><td class="target">${esc(item.target||'來源未提供評量目標')}${item.basis?`<small>${esc(item.basis)}</small>`:''}</td><td class="numeric">${rate(item.national)}</td><td class="numeric">${rate(item.city)}</td><td class="numeric">${rate(item.school)}</td><td class="numeric">${pp(difference(item,'national'))}</td><td class="numeric">${pp(difference(item,'city'))}</td><td class="numeric">${wrongCell(subject,item)}</td><td class="detail-cell"><button class="btn detail-button" type="button" data-detail="${esc(item.qid)}" aria-label="查看第 ${esc(item.qid)} 題詳情">查看</button></td></tr>`;}).join(''):'<tr><td colspan="10" class="empty">此篩選條件下沒有題目。</td></tr>'}</tbody><tfoot><tr class="footer-average"><td colspan="3">目前顯示題目平均<small>各欄列出有效題數；比較欄使用有效配對</small></td><td class="numeric">${averageCell(national.map(i=>i.national))}</td><td class="numeric">${averageCell(city.map(i=>i.city))}</td><td class="numeric">${averageCell(rows.map(i=>i.school))}</td><td class="numeric">${deltaAverageCell(rows,'national')}</td><td class="numeric">${deltaAverageCell(rows,'city')}</td><td class="numeric">—<small>不平均錯選率</small></td><td></td></tr></tfoot></table></div><p class="table-footnote">全國／臺中市平均僅使用同題學校與該基準皆有效的配對；學校欄使用目前顯示且有學校通過率的題目。差距 = 學校全體通過率 − 比較基準，不將所選等級群體直接與全國全體比較。最高錯選比例＝該錯誤選項人數÷本組有效人數。負值表示學校全體低於基準。選項百分比以該群體人數為分母，包含未作答與複選；${subject.id==='listening'?'聽力以 A、B、C 為實際選項，僅將實際錯誤選項納入最高錯選排序。':'錯誤選項嚴格大於 20% 標示集中錯選。這是本網頁教學標記，並非官方認定門檻。'} 若學校全體通過率高於全國或臺中市任一基準至少 10 ％，該題本組有實際錯選時另標示最高錯選選項（可 ≤20%）。缺少比較值不套用例外，「最多錯誤選項檢視」仍列出全部選擇題（含 0%），不受上述標記條件限制。</p>`;

}

function gapMarkup(subject){

 const rows=compareItems(subject).filter(i=>difference(i,state.baseline)<0).sort((a,b)=>difference(a,state.baseline)-difference(b,state.baseline)||a.number-b.number).slice(0,10);

 if(!rows.length)return '';

 const max=Math.max(...rows.map(i=>-difference(i,state.baseline)));

 return `<div class="panel lower-panel gap-panel"><h3>相對${baselineName()}落後前 ${rows.length} 題</h3><p class="muted small">按差距由小至大。條長表示落後幅度，共用尺度 0–${(max*100).toFixed(2)} ％。</p><div class="gap-chart">${rows.map(item=>`<div class="gap-row"><span>第 ${esc(item.qid)} 題</span><div class="gap-track" aria-hidden="true"><span style="width:${-difference(item,state.baseline)/max*100}%"></span></div><span class="gap-value">${(difference(item,state.baseline)*100).toFixed(2)} ％</span></div>`).join('')}</div></div>`;

}

function constructedMarkup(subject){

 const items=(subject.items||[]).filter(i=>i.kind==='constructed');if(!items.length)return '';

 return `<section class="panel lower-panel"><h3>數學非選擇題：分數分布</h3><p class="muted small">每題滿分 3 分。下列率值是平均得分，與選擇題通過率不同。來源 A／B／C／D 欄依序代表 0／1／2／3 分；未作答另列，計算分母仍包含未作答人數。</p><div class="constructed-grid">${items.map(item=>`<article class="constructed-card"><h3>第 ${esc(item.qid)} 題<button class="btn detail-button" data-detail="${esc(item.qid)}" type="button">查看題目</button></h3><p>${esc(item.target||'來源未提供評量目標')}</p><div class="table-wrap"><table><thead><tr><th>群體</th><th class="numeric">人數</th><th class="numeric">0 分</th><th class="numeric">1 分</th><th class="numeric">2 分</th><th class="numeric">3 分</th><th class="numeric">未答</th><th class="numeric">平均得分</th></tr></thead><tbody>${(subject.groups||[]).map(group=>{const g=item.groups?.[group.name];return `<tr><td>${esc(group.name)}</td><td class="numeric">${g?.n??'—'}</td>${['A','B','C','D','blank'].map(k=>`<td class="numeric">${g?.counts?.[k]??'—'}</td>`).join('')}<td class="numeric">${rate(g?.rate)}</td></tr>`;}).join('')}</tbody></table></div></article>`).join('')}</div></section>`;

}

function targetMarkup(subject){

 const grouped=new Map();choices(subject).forEach(item=>{const key=item.target||'未提供評量目標';if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(item);});

 return `<details class="collapsible"><summary>評量目標彙整（依來源文字分組）</summary><div class="collapsible-content"><p class="muted small">將評量目標文字完全相同的選擇題分組，計算逐題通過率平均。這是由逐題資料彙整的教學參考，不是官方分項成績；題數少的類別不宜過度推論。</p></div><div class="table-wrap"><table class="target-table"><thead><tr><th>評量目標</th><th class="numeric">題數</th><th class="numeric">學校平均（0–1）</th><th class="numeric">對全國平均差距</th><th class="numeric">對臺中市平均差距</th></tr></thead><tbody>${Array.from(grouped.entries()).map(([target,items])=>`<tr><td>${esc(target)}</td><td class="numeric">${items.length}</td><td class="numeric">${averageCell(items.map(i=>i.school))}</td><td class="numeric">${deltaAverageCell(items,'national')}</td><td class="numeric">${deltaAverageCell(items,'city')}</td></tr>`).join('')}</tbody></table></div></details>`;

}

function renderSubject(){

 const subject=current();if(!subject){document.getElementById('subject-content').innerHTML='<p class="empty">沒有可讀取的科目資料。</p>';return;}

 document.getElementById('history-content').innerHTML=historyMarkup(subject);

 const rows=shownItems(subject),compare=hasCompare(subject,state.baseline),groups=subject.groups||[];

 const totalN=groups.find(g=>g.name==='全體')?.n;

 const groupShare=g=>finite(totalN)&&totalN>0&&finite(g.n)?percent(g.n/totalN):'比例未提供';

 document.getElementById('subject-content').innerHTML=`<div class="panel"><div class="panel-head"><div class="subject-title-row"><div><h2>${esc(subject.name)}｜逐題分析</h2><p class="subject-source">來源：${esc(sourceName(subject))}</p></div><button class="btn" id="print-subject" type="button">列印本科</button></div><div class="groups">${groups.map(g=>`<span class="group-pill">${esc(g.name)}<strong class="number">${finite(g.n)?g.n:'—'}<em>人</em></strong><span class="group-share number" title="${esc(g.name)}人數 ÷ 全體人數 ${finite(totalN)?totalN:'未提供'}">${groupShare(g)}</span></span>`).join('')}</div><p class="small muted group-denominator">等級比例＝該等級人數÷本科全體有效人數（${finite(totalN)?totalN:'未提供'}人）；全體不含缺考及重大違規。${subject.id==='listening'?'聽力僅分基礎、待加強，不設精熟等級。':''}</p><p class="print-only print-note">本頁依目前篩選與排序列印。最高錯選使用「${esc(state.group)}」群體；率值顯示四位小數，差距單位為％。</p></div>${subjectHighlights(subject)}${summaryMarkup(subject)}${orderMarkup(subject)}<div class="controls"><label class="control">錯選分析群體<select id="group-control">${(subject.id==='listening'?['全體','基礎','待加強']:['全體','精熟','基礎','待加強']).map(name=>`<option value="${name}" ${state.group===name?'selected':''} ${groups.some(g=>g.name===name)?'':'disabled'}>${name}${groups.some(g=>g.name===name)?'':'（未提供）'}</option>`).join('')}</select></label></div>${tableMarkup(subject,rows)}${(subject.notes||[]).length?`<ul class="subject-notes">${subject.notes.map(note=>`<li>${esc(note)}</li>`).join('')}</ul>`:''}</div>${constructedMarkup(subject)}`;

 document.querySelectorAll('[data-order]').forEach(b=>b.addEventListener('click',()=>chooseOrder(b.dataset.order)));

 document.getElementById('group-control').addEventListener('change',event=>{state.group=event.target.value;renderSubject();});

 document.getElementById('print-subject').addEventListener('click',printSubject);

 document.querySelectorAll('[data-detail]').forEach(button=>button.addEventListener('click',()=>showDetail(button.dataset.detail)));

}

function optionCell(group,key,answer,constructed,listening,reviewStats){

 const count=group?.counts?.[key],proportion=finite(count)&&finite(group?.n)&&group.n>0?count/group.n:null;

 let cls='';

 if(listening&&key==='D')cls='record-only';

 else if(!constructed&&key===answer)cls='correct';

 else if(!constructed&&['A','B','C','D'].includes(key)&&key!==answer&&finite(proportion)&&proportion>0.2)cls='high-wrong';

 else if(!constructed&&reviewStats?.exception&&reviewStats.options.includes(key))cls='advantage-wrong';

 return `<td class="${cls}">${finite(count)?count:'—'}<small>${percent(proportion)}</small></td>`;

}



function teachingForQuestion(subject,item){

 const constructed=item.kind==='constructed',group=item.groups?.['全體'];

 const formatGap=b=>{const value=difference(item,b);return finite(value)?`${b==='national'?'校減全國':'校減臺中市'} ${(value*100).toFixed(2)}％`:`${b==='national'?'全國':'臺中市'}比較資料未提供`};

 let fact;

 if(constructed){

  const counts=group?.counts;

  fact=`學校全體平均得分${finite(item.school)?item.school.toFixed(4)+'分（滿分3分）':'未提供'}。`+

   (counts?['A','B','C','D'].map((k,i)=>`${i}分：${finite(counts[k])?counts[k]+'人':'未提供'}`).join('；')+'。':'得分分布未提供。');

 }else{

  const w=wrongStats(subject,item,'全體');

  fact=`全體通過率${percent(item.school)}；`+(w.options.length?`最高錯選${w.options.join('、')}，各占${percent(w.max)}`:finite(w.max)?'未有實際錯選':'錯選資料未提供')+`；${formatGap('national')}；${formatGap('city')}。`;

 }

 const focus=item.target||item.basis||'本題對應能力';

 const fallback={

  fact,

  hypothesis:constructed?`得分分布可作為檢視「${focus}」的線索。需查看學生的計算、推理與表達步驟，才能區分觀念理解、運算或書寫上的困難。`:`選項分布可作為檢視「${focus}」的線索；尚不能單由選答判定錯誤原因。`,

  action:constructed?'請學生逐步說明解題策略，依評分規準對照完整與部分給分作答；針對缺漏步驟示範修正，再以同能力短題確認理解。':

   subject.id==='listening'?'重播本題對應音檔，請學生說明聽到的關鍵訊息並對照選項；確認誤聽或語意理解的可能問題，再以相近情境檢核。':

   subject.id==='math'?'請學生呈現解題步驟，對照正答與主要錯選，檢查概念、運算及題意理解；再以同分項能力短題檢核。':

   '請學生口述解題依據，對照正答與主要錯選，標出題目或題組中的證據；以同評量目標的短題再次檢查理解。'

 };

 return {fact:item.teaching?.fact||fallback.fact,hypothesis:item.teaching?.hypothesis||fallback.hypothesis,action:item.teaching?.action||fallback.action};

}

function showDetail(qid){

 const subject=current(),item=subject.items.find(i=>i.qid===qid);if(!item)return;

 const constructed=item.kind==='constructed',listening=subject.id==='listening';

 const teaching=teachingForQuestion(subject,item);

 document.getElementById('dialog-eyebrow').textContent=subject.name+' · '+(constructed?'非選擇題':'選擇題');

 document.getElementById('dialog-title').textContent='第 '+item.qid+' 題';

 const keys=constructed?['A','B','C','D','blank','multiple']:listening?['A','B','C','blank','multiple']:['A','B','C','D','blank','multiple'];

 const labels=key=>constructed?({A:'0 分',B:'1 分',C:'2 分',D:'3 分',blank:'未作答',multiple:'複選紀錄'}[key]):({D:listening?'來源 D 欄紀錄':'D',blank:'未作答',multiple:'複選'}[key]||key);

 document.getElementById('dialog-body').innerHTML=`<section class="detail-section question-first"><h3>題目與選項</h3><div class="collapsible-content">${item.doc?`<p class="doc-source">${esc(item.doc.note||'來源：隨附 DOCX 題目資料')}</p><div class="doc-fragment" id="doc-fragment"></div>`:'<p class="muted small">未提供可對應的原始題目內容；本題分析僅使用試題分析表。</p>'}</div></section><div class="detail-meta"><div class="meta-box"><span class="label">${constructed?'評分範圍':'正確答案'}</span><strong>${constructed?'0–3 分':esc(item.answer||'來源未提供')}</strong></div><div class="meta-box"><span class="label">${constructed?'學校平均得分（滿分 3）':'學校通過率（0–1）'}</span><strong class="number">${rate(item.school)}</strong></div><div class="meta-box wide"><span class="label">來源評量目標</span>${esc(item.target||'未提供')}</div>${item.basis?`<div class="meta-box wide"><span class="label">來源評量依據</span>${esc(item.basis)}</div>`:''}</div><section class="detail-section"><h3>${constructed?'各群體得分分布':'各群體選項分布'}</h3><p class="small muted">每格上列為人次，下列為占該群體人數的百分比。${constructed?'平均得分以全部群體人數為分母，包含未作答。':'分母包含未作答、複選與來源紀錄的其他作答。'}</p>${constructed?'':`<div class="legend"><span class="correct-key">正確選項</span><span class="wrong-key">錯誤選項 >20%</span><span class="advantage-key">學校高於基準 ≥10 ％的最高錯選（≤20%）</span></div>`}<div class="table-wrap"><table class="option-table"><thead><tr><th scope="col">選項／作答情形</th>${(subject.groups||[]).map(group=>`<th scope="col">${esc(group.name)}</th>`).join('')}</tr></thead><tbody><tr><th scope="row">人數</th>${(subject.groups||[]).map(group=>`<td>${finite(item.groups?.[group.name]?.n)?item.groups[group.name].n:'—'}</td>`).join('')}</tr>${keys.map(k=>`<tr><th scope="row">${esc(labels(k))}</th>${(subject.groups||[]).map(group=>optionCell(item.groups?.[group.name],k,item.answer,constructed,listening,constructed?null:wrongStats(subject,item,group.name))).join('')}</tr>`).join('')}<tr><th scope="row">${constructed?'平均得分':'通過率（0–1）'}</th>${(subject.groups||[]).map(group=>`<td>${rate(item.groups?.[group.name]?.rate)}</td>`).join('')}</tr></tbody></table></div>${listening?'<div class="notice">英文聽力只有 A、B、C 三個選項，能力等級分為基礎、待加強。全體為合計群體，並非另一個等級；各選項比例以該群體人數為分母。</div>':''}${constructed?'<div class="notice">來源 A／B／C／D 欄依序對應 0／1／2／3 分。平均得分 =（1 分人數 + 2 × 2 分人數 + 3 × 3 分人數）÷ 群體人數，並非答對比例。</div>':''}${constructed?'':`<div class="notice">錯選重點標記採兩個條件擇一（不作為全部題目排序的篩選門檻）：本組單一錯誤選項 >20%；或學校全體通過率高於全國／臺中市任一基準至少 10 ％，且本組有實際錯選。後者即使最高錯選 ≤20% 也另外標示，不稱為集中錯選。20%與10％為本網頁教學標記，並非官方判定標準；錯選原因仍需搭配學生說明確認。<br>${['national','city'].filter(b=>finite(difference(item,b))).map(b=>`校減${b==='national'?'全國':'臺中市'}：${(difference(item,b)*100).toFixed(2)} ％`).join('；')||'本題未提供外部比較值，無法套用高於基準的例外。'}</div>`}</section>${teaching?`<section class="detail-section"><h3>教學檢視</h3><div class="teaching-grid"><div class="teaching-box"><h4>數據事實</h4><p>${esc(teaching.fact||'未提供')}</p></div><div class="teaching-box"><h4>待驗證的可能原因</h4><p>${esc(teaching.hypothesis||'需搭配作答歷程確認。')}</p></div><div class="teaching-box"><h4>教學行動建議</h4><p>${esc(teaching.action||'未提供')}</p></div></div></section>`:''}`;

 if(item.doc?.html)document.getElementById('doc-fragment').innerHTML=item.doc.html;

 const dialog=document.getElementById('item-dialog');dialog.showModal();dialog.scrollTop=0;

}

function trendChange(row,year){

 const now=row.years.find(x=>x.year===115).gap,old=row.years.find(x=>x.year===year).gap;

 if(!finite(now)||!finite(old))return '資料未提供，無法比較';

 const delta=now-old,amount=(Math.abs(delta)*100).toFixed(0);

 if(Math.abs(delta)<1e-9)return '差距持平';

 if(now<=0&&old<=0)return `落差${delta>0?'縮小':'擴大'} ${amount} ％（${delta>0?'變強':'變弱'}）`;

 if(now>=0&&old>=0)return `優勢${delta>0?'擴大':'縮小'} ${amount} ％`;

 return `由${old<0?'落後轉為領先':'領先轉為落後'}（差距${delta>0?'增加':'減少'} ${amount} ％）`;

}

function historyMarkup(subject){

 const rows=subject.abilityHistory||[];

 if(!rows.length)return '';

 return `<section class="panel lower-panel ability-history" aria-labelledby="history-title"><h3 id="history-title">${esc(subject.name)}｜近三年分項能力比較</h3><p class="small muted">來源：各科分項能力通過率分析。依官方分項能力報告呈現，不以本頁逐題均值替代。</p><div class="table-wrap"><table class="history-table"><thead><tr><th>分項能力</th>${[113,114,115].map(y=>`<th>${y} 年</th>`).join('')}<th>115 年較 114 年</th><th>115 年較 113 年</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.ability)}</th>${r.years.map(y=>`<td><div>學校 <strong>${finite(y.school)?(y.school*100).toFixed(0)+'%':'未提供'}</strong></div><div>全國 ${(y.national*100).toFixed(0)}%</div><div>校減國 ${pp(y.gap)}</div></td>`).join('')}<td>${trendChange(r,114)}</td><td>${trendChange(r,113)}</td></tr>`).join('')}</tbody></table></div><p class="small muted history-note">各年為不同屆學生、不同試題；差距變化描述相對全國的位置，不能視為同一批學生的進步或退步。來源通過率保留兩位小數，差距及變化以來源精度計算。</p></section>`;

}

function renderGrades(){

 const grades=DATA.gradeOverview||[];

 document.getElementById('grade-overview').innerHTML=`<div class="section-heading"><div><h2>五科精熟、基礎、待加強等級比較</h2><p class="small muted">英語採正式「整體能力」等級；不將閱讀、聽力比例平均。</p></div></div><div class="panel"><div class="table-wrap"><table class="grade-table"><thead><tr><th>科目</th><th>等級</th><th class="numeric">學校</th><th class="numeric">全國</th><th class="numeric">臺中市</th><th class="numeric">學校－全國</th><th class="numeric">學校－臺中市</th></tr></thead><tbody>${grades.map(s=>s.levels.map((g,i)=>`<tr>${i===0?`<th scope="rowgroup" rowspan="3">${esc(s.name)}<small class="grade-absent">缺考率 ${percent(s.absentRate)}</small></th>`:''}<th scope="row">${esc(g.name)}</th><td class="numeric">${percent(g.school)}</td><td class="numeric">${percent(g.national)}</td><td class="numeric">${finite(g.city)?percent(g.city):'<span class="missing">未提供整體等級</span>'}</td><td class="numeric">${pp(g.deltaNational)}</td><td class="numeric">${finite(g.deltaCity)?pp(g.deltaCity):'<span class="missing">無法計算</span>'}</td></tr>`).join('')).join('')}</tbody></table></div><div class="grade-notes"><p>學校等級比例以本科有效作答人數為分母，扣除缺考及重大違規；缺考率另列。國文、數學、社會、自然的分組人數已與正式比例核對。英語整體比例直接引用正式報告。比例四捨五入後合計可能不是 100%。</p><p>全國採<a href="${esc(DATA.nationalGradeSource)}" target="_blank" rel="noopener">教育部115年各科等級加標示人數百分比統計表</a>，有效人數：${grades.map(s=>`${esc(s.name)} ${s.nationalN.toLocaleString()} 人`).join('、')}。此公開統計口徑與學力品質監控逐題報告不完全相同；不混用兩者分母。臺中市有效人數：${grades.filter(s=>s.cityN).map(s=>`${esc(s.name)} ${s.cityN.toLocaleString()} 人`).join('、')}。</p><p>差距單位為％，正負僅表示該等級比例較高或較低；待加強比例較高不代表表現較好。臺中市國文、數學、社會、自然的等級比例＝市級詳細試題分析各組人數÷全體有效人數。英語整體能力比例直接引用縣市政府版學生成績報告的「臺中市」彙整列：待加強25.86%、基礎48.16%、精熟25.97%；來源四捨五入後合計99.99%，不另行調整比例，也不由閱讀／聽力推算。缺考率不得加進各等級比例。</p><details class="official-grade-charts"><summary>查看五科官方學校／全國／臺中市比較原圖</summary><div class="grade-chart-grid">${grades.map(s=>`<figure><figcaption>${esc(s.name)}（學生成績報告第 ${s.chartPage} 頁）</figcaption><img src="${s.chart}" alt="${esc(s.name)}官方等級比例比較圖，包含全國、臺中市及學校；縣市未標示精確數值" loading="lazy"></figure>`).join('')}</div></details></div></div>`;

}



function renderMethods(){

 const issues=(DATA.issues||[]).filter(issue=>!(issue.subject==='英文聽力'&&issue.field==='來源D欄紀錄'));

 document.getElementById('methods').innerHTML=`<details class="collapsible"><summary>來源與分析方法</summary><div class="collapsible-content"><section class="guide-summary" aria-labelledby="guide-summary-title" style="margin-bottom:24px"><h3 id="guide-summary-title">《國中教育會考學力品質監控資料【國民中學版】使用說明》摘要</h3><p class="small muted" style="margin-top:6px">依本校資料夾內的使用說明整理。四類資料由整體學力、分項能力、逐題通過率到選項反應，協助教師找出學習優勢與弱點，作為調整教學的參考。</p><ul><li><strong>學生成績報告：</strong>提供學校基本資料、各科各等級人數百分比與表現描述；比較學校、全國與所在縣市的學力狀況。本網頁對應「五科精熟、基礎、待加強等級比較」。</li><li><strong>各科分項能力通過率分析：</strong>提供近三年學校與全國各分項能力通過率，以全國平均為參照觀察變化。若某能力低於全國且差距逐年擴大，可列為優先補強方向。本網頁對應「五科近三年分項能力比較」。</li><li><strong>各科試題通過率分析：</strong>提供每題的分項能力、評量目標及學校、縣市、全國通過率，供教師篩選需討論的題目。使用說明舉例可篩選學校通過率低於 0.5（50%），或低於縣市通過率的題目；這些是篩選示例，不是統一判定標準。本網頁以逐題差距及分項能力排序支援檢視。</li><li><strong>各科試題分析：</strong>提供完整試題、評量目標、命題依據、通過率、鑑別度及各選項選答人次。教師可比較全體與不同程度群體的作答，從低通過率題目的選項分布探討可能的迷思概念，並調整教學。本網頁對應逐題「查看」詳情。</li></ul><p class="small muted">檔案形式：前三類均有 PDF 與 XLSX；各科試題分析有六份 DOCX 與六份 XLSX。</p><div class="notice"><strong>本網頁補充判讀：</strong>不同年度為不同屆學生及試題，跨年差距不能視為同一批學生的成長；錯選只能提供待確認的線索，需搭配作答說明與課堂觀察。英文聽力僅有 A、B、C 選項及基礎、待加強兩等級。「錯選 &gt;20%」等醒目標記為本網頁設定，並非使用說明所訂門檻。</div></section><div class="method-columns"><div><h3>計算與判讀</h3><ul><li>選擇題通過率以來源資料為準；表中率值使用 0–1，顯示四位小數。</li><li>選擇題逐題均值採有效題目算術平均，不換算為測驗總分。</li><li>差距以同題有效配對計算：100 ×（學校通過率 − 比較基準通過率），單位為％。</li><li>「最多錯誤選項檢視」列出全部選擇題，按本組每題最高錯選率由高至低排列，含低於 20% 與 0% 的題目；缺少資料置末。錯選重點標記符合任一條件即標示：① 本組單一錯誤選項人次 ÷ 本組人數 >20%；② 學校全體通過率－全國或縣市通過率 ≥0.10，且本組有實際錯選。第二種情況標示最高錯選，不要求 >20%。</li><li>「高出10%」依通過率相減解讀為至少10％，例如80%－70%=10％；全國、縣市任一符合即可，不受檢視基準選單影響。正答、未作答、複選與非實際選項不納入錯選條件。</li><li>未作答與複選另列紀錄；英文聽力僅呈現 A、B、C 三個選項，等級僅分基礎、待加強。</li><li>數學非選擇題以平均得分與分數分布獨立呈現，不混入通過率均值。</li></ul></div><div><h3>資料限制與判讀邊界</h3><ul>${(DATA.limitations||[]).map(note=>`<li>${esc(note)}</li>`).join('')}</ul></div></div></div><div class="table-wrap"><table class="sources-table"><thead><tr><th>來源檔案</th><th>用途</th></tr></thead><tbody>${(DATA.sources||[]).map(source=>`<tr><td>${esc(source.name)}</td><td>${esc(source.role)}</td></tr>`).join('')}</tbody></table></div></details><details class="collapsible"><summary>資料核對與例外記錄（${issues.length} 項）</summary><div class="collapsible-content"><h3>核對結果</h3><ul>${(DATA.verification||[]).map(note=>`<li>${esc(note.replaceAll('30%','20%'))}</li>`).join('')}<li>英文聽力僅有 A、B、C 三個選項，能力等級為基礎、待加強；來源 D 欄不列為本報告的資料例外。</li></ul>${!issues.length?'<p class="small muted">未列出需另行註記的資料例外。</p>':''}</div>${issues.length?`<div class="table-wrap"><table class="issues-table"><thead><tr><th>科目</th><th>題號</th><th>欄位</th><th>核對說明</th></tr></thead><tbody>${issues.map(issue=>`<tr><td>${esc(issue.subject)}</td><td>${esc(issue.qid||'—')}</td><td>${esc(issue.field)}</td><td>${esc(issue.message)}</td></tr>`).join('')}</tbody></table></div>`:''}</details>`;

}

let printBackup=null;

function printSubject(){

 const dialog=document.getElementById('item-dialog');if(dialog.open)dialog.close();

 printBackup=null;

 requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));

}

window.addEventListener('afterprint',()=>{if(printBackup){Object.assign(state,printBackup);printBackup=null;renderSubject();}});

function render(){renderOverview();renderSubject();}

const reportTitle=(DATA.school||'學校名稱')+(DATA.year||115)+'會考成績分析';

document.title=reportTitle;

document.getElementById('report-title').textContent=reportTitle;

document.getElementById('school-line').textContent='學校代碼 '+(DATA.schoolCode||'未提供');

document.getElementById('print-top').addEventListener('click',printSubject);

document.getElementById('close-dialog').addEventListener('click',()=>document.getElementById('item-dialog').close());

document.getElementById('item-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close();}});

render();renderMethods();renderGrades();
